PRAGMA foreign_keys = ON;
CREATE TABLE leagues(id TEXT PRIMARY KEY, source_code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, provider_id INTEGER, coverage_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE teams(id TEXT PRIMARY KEY, name TEXT NOT NULL, provider_id TEXT);
CREATE TABLE team_aliases(source TEXT NOT NULL, alias TEXT NOT NULL, team_id TEXT NOT NULL REFERENCES teams(id), status TEXT NOT NULL DEFAULT 'unverified', PRIMARY KEY(source,alias));
CREATE TABLE fixtures(id TEXT PRIMARY KEY, provider_fixture_id TEXT UNIQUE, league_id TEXT NOT NULL REFERENCES leagues(id), season TEXT NOT NULL, home_id TEXT NOT NULL REFERENCES teams(id), away_id TEXT NOT NULL REFERENCES teams(id), match_date TEXT NOT NULL, kickoff_utc TEXT, status TEXT NOT NULL, home_goals INTEGER, away_goals INTEGER, source TEXT NOT NULL, source_updated_at TEXT, fetched_at TEXT NOT NULL, quality TEXT NOT NULL, CHECK(home_id<>away_id), CHECK(home_goals IS NULL OR home_goals>=0), CHECK(away_goals IS NULL OR away_goals>=0));
CREATE INDEX fixtures_date ON fixtures(league_id,match_date,kickoff_utc);
CREATE TABLE features(fixture_id TEXT PRIMARY KEY REFERENCES fixtures(id), feature_version TEXT NOT NULL, information_cutoff_date TEXT NOT NULL, payload TEXT NOT NULL, snapshot_hash TEXT NOT NULL);
CREATE TABLE model_versions(version TEXT PRIMARY KEY, algorithm TEXT NOT NULL, training_cutoff TEXT NOT NULL, source_commit TEXT NOT NULL, dataset_version TEXT NOT NULL, digest TEXT NOT NULL, metadata TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'candidate');
CREATE TABLE registry(id INTEGER PRIMARY KEY CHECK(id=1), active_version TEXT REFERENCES model_versions(version), previous_version TEXT REFERENCES model_versions(version));
INSERT INTO registry(id) VALUES(1);
CREATE TABLE predictions(id TEXT PRIMARY KEY, fixture_id TEXT NOT NULL REFERENCES fixtures(id), model_version TEXT NOT NULL, generated_at TEXT NOT NULL, information_cutoff_date TEXT NOT NULL, stage TEXT NOT NULL, probabilities TEXT NOT NULL, expected_home_goals REAL, expected_away_goals REAL, scorelines TEXT NOT NULL, feature_snapshot_hash TEXT NOT NULL, locked INTEGER NOT NULL DEFAULT 0 CHECK(locked IN(0,1)), source TEXT NOT NULL, UNIQUE(fixture_id,model_version,stage));
CREATE TRIGGER immutable_locked_prediction BEFORE UPDATE ON predictions WHEN OLD.locked=1 BEGIN SELECT RAISE(ABORT,'locked_prediction_immutable'); END;
CREATE TRIGGER no_locked_delete BEFORE DELETE ON predictions WHEN OLD.locked=1 BEGIN SELECT RAISE(ABORT,'locked_prediction_immutable'); END;
CREATE TRIGGER valid_prediction_cutoff BEFORE INSERT ON predictions WHEN NEW.information_cutoff_date >= (SELECT match_date FROM fixtures WHERE id=NEW.fixture_id) OR NEW.generated_at >= (SELECT kickoff_utc FROM fixtures WHERE id=NEW.fixture_id) BEGIN SELECT RAISE(ABORT,'prediction_after_cutoff'); END;
CREATE TABLE evaluations(prediction_id TEXT PRIMARY KEY REFERENCES predictions(id), outcome INTEGER NOT NULL, log_loss REAL NOT NULL, brier REAL NOT NULL, evaluated_at TEXT NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY, status TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, detail TEXT);
CREATE TABLE job_locks(key TEXT PRIMARY KEY, owner TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE quota_windows(id TEXT PRIMARY KEY, used INTEGER NOT NULL DEFAULT 0, remaining INTEGER NOT NULL DEFAULT 100, last_request_at INTEGER NOT NULL DEFAULT 0, blocked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE api_usage(id TEXT PRIMARY KEY, window_id TEXT NOT NULL, attempted_at INTEGER NOT NULL, route TEXT NOT NULL, status INTEGER, remaining INTEGER);
CREATE INDEX api_usage_time ON api_usage(attempted_at);
CREATE TABLE response_cache(key TEXT PRIMARY KEY, payload TEXT NOT NULL, expires_at INTEGER NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE nonces(nonce TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE audit_log(id TEXT PRIMARY KEY, action TEXT NOT NULL, created_at TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES('MODEL_AUTO_PROMOTE','false');
CREATE TABLE performance(id TEXT PRIMARY KEY, payload TEXT NOT NULL);
